// Read the officially managed n8n Data Table. NEVER infer safe sending from a user-editable row.
// Missing, duplicate, stale, or conflicting portfolio evidence remains blocked.
const raw=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(raw.some(x=>x.error))return [{json:{mode:'READ_ONLY',reason:'N8N_DATA_TABLE_NOT_AVAILABLE',status:'BLOCKED',portfolios:[],canSend:false}}];
if(!raw.length)return [{json:{mode:'READ_ONLY',reason:'NO_PORTFOLIO_CONTROL_ROWS',status:'BLOCKED',portfolios:[],canSend:false}}];
if(raw.length>50)throw new Error('PORTFOLIO_CONTROL_TOO_MANY_ROWS');
const seen=new Set(),now=Date.now();
function recent(t,h){const ms=Date.parse(t);return Number.isFinite(ms)&&ms<=now&&now-ms<=h*3600000;}
const p=raw.map(x=>{
  const id=String(x.portfolioId||'').trim();
  const holds=[];
  if(!id||seen.has(id))holds.push('MISSING_OR_DUPLICATE_PORTFOLIO_ID');
  seen.add(id);
  if(x.masterSendingEnabled!==true)holds.push('MASTER_DISABLED');
  if(x.operatorLiveApproved!==true)holds.push('OPERATOR_APPROVAL_NOT_VERIFIED');
  if(x.providerAnalyticsVerified!==true)holds.push('ANALYTICS_NOT_VERIFIED');
  if(x.accountHealthVerified!==true)holds.push('ACCOUNT_HEALTH_NOT_VERIFIED');
  if(!Number.isSafeInteger(x.messagingTier)||x.messagingTier<=0||!recent(x.tierVerifiedAt,24))holds.push('TIER_UNKNOWN_OR_STALE');
  if(!recent(x.qualityVerifiedAt,24))holds.push('QUALITY_UNKNOWN_OR_STALE');
  if(x.externalUsageUnknown!==false||!Number.isSafeInteger(x.externalUnique24h)||x.externalUnique24h<0||
     !recent(x.externalUsageVerifiedAt,24))holds.push('EXTERNAL_USAGE_UNKNOWN_OR_STALE');
  if(x.unresolvedCycle!==false||String(x.activeCycleId||'').trim())holds.push('UNRESOLVED_CYCLE');
  const completion=x.lastVerifiedBatchCompletedAt;
  if(completion && (isNaN(Date.parse(completion))||now-Date.parse(completion)<26*3600000))holds.push('GLOBAL_26_HOUR_GAP_OR_INVALID_COMPLETION');
  if(!Number.isSafeInteger(x.rollingReserved24h)||x.rollingReserved24h<0)holds.push('RESERVATION_LEDGER_NOT_VERIFIED');
  const capacity=Number.isSafeInteger(x.messagingTier)&&Number.isSafeInteger(x.externalUnique24h)&&Number.isSafeInteger(x.rollingReserved24h)?
    Math.max(0,x.messagingTier-x.externalUnique24h-x.rollingReserved24h):null;
  if(capacity===0)holds.push('NO_RECORDED_HEADROOM');
  holds.push('DATA_TABLE_IS_NOT_ATOMIC_SEND_AUTHORITY','META_LIVE_CAPACITY_NOT_INDEPENDENTLY_PROVEN');
  return {portfolioId:id||null,recordedTier:x.messagingTier??null,estimatedHeadroom:capacity,
   holds,canSend:false};
});
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',status:'BLOCKED',portfolioCount:p.length,
 portfolios:p,canSend:false,crmEventWriteAuthorized:false,diagnosticOnly:true}}];
